commands.command:
set -eu
if ! getent passwd infraset-nodejs >/dev/null 2>&1; then sudo adduser --system --group --home /nonexistent --no-create-home infraset-nodejs; fi
sudo install -d -o root -g root -m 0755 /opt/infraset-nodejs
sudo tee /opt/infraset-nodejs/server.js >/dev/null <<'ANTRIEB_NODE_EOF'
'use strict';
var http = require('http');
var host = '127.0.0.1';
var port = 3000;
var body = 'infraset-nodejs';

var server = http.createServer(function (request, response) {
  response.writeHead(200, {
    'Content-Type': 'text/plain',
    'Content-Length': Buffer.byteLength(body)
  });
  response.end(body);
});

server.listen(port, host, function () {
  console.log('infraset-nodejs listening on ' + host + ':' + port);
});
ANTRIEB_NODE_EOF
sudo chown root:root /opt/infraset-nodejs/server.js
sudo chmod 0644 /opt/infraset-nodejs/server.js
printf 'app-installed\n'
